class LockingTree {
    vector<int>par,owner;
    vector<vector<int>>child;
    bool clearDesc(int u){bool found=false;
        for(int v:child[u]){
            if(owner[v]!=-1){owner[v]=-1;found=true;}
            if(clearDesc(v))found=true;
        }
        return found;
    }
public:
    LockingTree(vector<int>& parent):par(parent),owner(parent.size(),-1),child(parent.size()){
        for(int i=1;i<(int)parent.size();++i)child[parent[i]].push_back(i);
    }
    bool lock(int num,int user){if(owner[num]!=-1)return false;owner[num]=user;return true;}
    bool unlock(int num,int user){if(owner[num]!=user)return false;owner[num]=-1;return true;}
    bool upgrade(int num,int user){
        if(owner[num]!=-1)return false;
        for(int p=par[num];p!=-1;p=par[p])if(owner[p]!=-1)return false;
        if(!clearDesc(num))return false;
        owner[num]=user;return true;
    }
};
